  "Linen kilts, pleated New Kingdom robes, Coptic tunics and early Islamic layers, era by era.":
    "التنانير الكتان، أرواب الدولة الحديثة المطوية، الستر القبطية والطبقات الإسلامية المبكرة، حقبة بحقبة.",
  "Linguistic continuity": "الاستمرارية اللغوية",
  "Living practices traced across millennia": "ممارسات معيشية متتبعة عبر آلاف السنين",
  "Local Producers": "منتجون محليون",
  "Locally produced collections": "مجموعات منتجة محلياً",
  "Long before the 27 governorates, Egypt was 42 nomes, then Roman provinces, then Coptic bishoprics, then Islamic wilayat and Mamluk iqta'. The borders moved; the logic never did — the river organises the country. Read the ancient province map next to today's administrative divisions and the continuity becomes obvious: the same clusters of settlement, the same corridors, the same names surviving in modern towns.":
    "قبل المحافظات الـ27 بوقت طويل، كانت مصر 42 إقليماً، ثم ولايات رومانية، ثم أبرشيات قبطية، ثم ولايات إسلامية وإقطاعيات مملوكية. الحدود تحركت؛ أما المنطق فلم يتغير أبداً — فالنهر ينظم البلاد. اقرأ خريطة المقاطعات القديمة بجوار التقسيمات الإدارية اليوم وستصبح الاستمرارية واضحة: نفس تجمعات الاستيطان، نفس الممرات، نفس الأسماء باقية في المدن الحديثة.",
  "Loyalty & Rewards": "الولاء والمكافآت",
