  "Copper hammered in the same alleys since the Mamluks, looms still threaded by hand, spice sacks opened at dawn, fields worked at the pace of the flood. Egypt's crafts are not heritage displays — they are working businesses you can visit, commission from and buy. This chapter opens the workshops, the souks, the farms and the ordinary street so travellers can plan a day inside the real economy of the country.":
    "Cuivre martelé dans les mêmes allées depuis les Mamelouks, métiers à tisser toujours enfilés à la main, sacs d'épices ouverts à l'aube, champs travaillés au rythme de la crue. Les métiers d'art égyptiens ne sont pas des expositions patrimoniales — ce sont des entreprises en activité que vous pouvez visiter, auprès desquelles vous pouvez commander et acheter. Ce chapitre ouvre les ateliers, les souks, les fermes et la rue ordinaire afin que les voyageurs puissent planifier une journée au cœur de la véritable économie du pays.",
  "Copper, clay, glass, palm fibre and applique — living crafts practised in the same quarters for centuries. Meet the makers, watch the work, buy directly at fair prices.":
    "Cuivre, argile, verre, fibre de palmier et appliqué — des métiers d'art vivants pratiqués dans les mêmes quartiers depuis des siècles. Rencontrez les artisans, observez le travail, achetez directement à des prix équitables.",
  "Copper, glass and lanterns with a craft guide.":
    "Cuivre, verre et lanternes avec un guide artisanal.",
