  "Egyptian dress across the 27 governorates": "Vêtement égyptien à travers les 27 gouvernorats",
  "Egyptian dress from Ayyubid to modern Egypt":
    "Vêtement égyptien de l'époque ayyoubide à l'Égypte moderne",
