    "Épices égyptiennes et hibiscus dans des bols en cuivre",
  "Egyptian tailoring, textiles and handmade crafts":
    "Confection égyptienne, textiles et artisanat fait main",
  "Egyptians have been baking, brewing and pickling on the same riverbank for five thousand years. Ful and taameya open the morning, molokhia and mahshi hold the family lunch, and hibiscus, sugarcane and mint tea close the night. The plates below trace the line from ancient jars and clay pitchers to the street classics visitors queue for today — a cuisine that never needed reinvention because it never stopped being cooked.":
    "Les Égyptiens cuisinent, brassent et marinent sur la même rive du fleuve depuis cinq mille ans. Le foul et le taameya ouvrent le matin, la molokhia et le mahshi composent le déjeuner familial, et l'hibiscus, la canne à sucre et le thé à la menthe closent la nuit. Les assiettes ci-dessous retracent la lignée des anciens pots et pichets d'argile jusqu'aux classiques de rue pour lesquels les visiteurs font la queue aujourd'hui — une cuisine qui n'a jamais eu besoin d'être réinventée parce qu'elle n'a jamais cessé d'être préparée.",
  "Eight illustrated chapters that turn a national archive into something you can browse, plan a trip around and invest in. Every plate is documented, every era is placed, and every chapter connects to a live part of the platform.":
    "Huit chapitres illustrés qui transforment une archive nationale en quelque chose que vous pouvez parcourir, autour duquel vous pouvez planifier un voyage et dans lequel vous pouvez investir. Chaque planche est documentée, chaque ère est située, et chaque chapitre se connecte à une partie vivante de la plateforme.",
  "El Gouna": "El Gouna",
  "El Tor": "El Tor",
  "Endless stories": "Histoires infinies",
  "English text": "Texte en anglais",
  "Enquire & order": "Demander et commander",
  Entertainment: "Divertissement",
  "Entertainment & Leisure": "Divertissement et loisirs",
  "Entertainment Investment": "Investissement dans le divertissement",
  "Epics & defence": "Épopées et défense",
  "Epics of Egypt through the ages": "Épopées d'Égypte à travers les âges",
  "Eras of rulers documented": "Ères des dirigeants documentées",
  "Eras ready for production": "Ères prêtes pour la production",
  Events: "Événements",
  "Events & Festivals": "Événements et festivals",
  "Every era in this encyclopedia is a script waiting for a camera. Egypt One's film desk exists to turn documented history into world-class Egyptian films, series and animation — shot in Egypt, produced by Egyptian talent, distributed globally. For investors it is a pipeline: studios, locations, post-production, training and film tourism. For visitors it is a reason to stand where the scene was shot.":
    "Chaque ère de cette encyclopédie est un scénario en attente d'une caméra. Le département cinématographique d'Egypt One a pour mission de transformer l'histoire documentée en films, séries et animations égyptiens de classe mondiale — tournés en Égypte, produits par des talents égyptiens, distribués mondialement. Pour les investisseurs, c'est un pipeline : studios, lieux de tournage, post-production, formation et tourisme cinématographique. Pour les visiteurs, c'est une raison de se tenir là où la scène a été filmée.",
  "Every flag Egypt has raised tells you who was standing on the riverbank that century. The crescent of the Khedivate, the tricolour of 1952, the two stars of the United Arab Republic, the Eagle of Saladin still on the mast today — read in sequence, they are a national autobiography in cloth. Beside them stand the coats of arms, the official flags of the state's institutions, and the anthems Egyptians have sung from *Salam Li Misr* to *Bilady, Bilady, Bilady*.":
    "Chaque drapeau qu'a hissé l'Égypte révèle qui se tenait sur la rive du fleuve durant ce siècle. Le croissant du Khédivat, le tricolore de 1952, les deux étoiles de la République arabe unie, l'Aigle de Saladin toujours au mât aujourd'hui — lus en séquence, ils constituent une autobiographie nationale tissée. À leurs côtés se dressent les armoiries, les drapeaux officiels des institutions de l'État, et les hymnes que les Égyptiens ont chantés de *Salam Li Misr* à *Bilady, Bilady, Bilady*.",
  "Every listed mill carries a traceable certification code.":
    "Chaque moulin listé porte un code de certification traçable.",
  "Evolution of the Egyptian flag through the ages":
    "Évolution du drapeau égyptien à travers les âges",
