  "From Miescher in 1869 to the first complete Old Kingdom genome and the national genome centre.":
    "De Miescher en 1869 au premier génome complet de l'Ancien Empire et au centre national du génome.",
  "From pre-dynastic to Fatimid": "Du prédynastique au fatimide",
  "From the Fourth Cataract to the Euphrates: military, political and cultural projection.":
    "De la quatrième cataracte à l'Euphrate : projection militaire, politique et culturelle.",
  "From the Ottoman era to the present tricolour, with the story behind each change.":
    "De l'ère ottomane au tricolore actuel, avec l'histoire derrière chaque changement.",
  "From the embroidered Siwan gowns of the Western Desert to the indigo galabeyas of the Delta, Egyptian dress is a living map. Each governorate keeps its own stitch, colour code and headwrap — patterns that travelled with caravans, harvests and weddings for centuries. This chapter lays the whole republic side by side so a visitor can see, in one glance, how Cairo, Sinai, Nubia and the coast dress differently while sharing one thread.":
    "Des robes brodées siwan du désert occidental aux galabeyas indigo du Delta, la tenue égyptienne est une carte vivante. Chaque gouvernorat conserve son point de couture, son code couleur et son foulard — des motifs qui ont voyagé avec les caravanes, les récoltes et les mariages pendant des siècles. Ce chapitre présente l'ensemble de la république côte à côte afin qu'un visiteur puisse voir, en un coup d'œil, comment Le Caire, le Sinaï, la Nubie et la côte s'habillent différemment tout en partageant un fil conducteur.",
