  "How authority dressed itself — from pharaonic regalia to Khedivial uniforms and modern protocol.":
    "Comment l'autorité se revêtait — des insignes pharaoniques aux uniformes khédiviaux et au protocole moderne.",
  Hurghada: "Hurghada",
  "Hurghada marinas": "Marinas d'Hurghada",
  "In 2025 the first complete genome of an Old Kingdom individual — around 4,500 years old — was sequenced and published. It confirmed what the language, the crafts and the faces already suggested: modern Egyptians carry substantial genetic continuity with the ancient population of the valley, with natural admixture over millennia of trade and conquest. The Egyptian Reference Genome Project now targets 25,000 genomes and a national genome centre.":
    "En 2025, le premier génome complet d'un individu de l'Ancien Empire — vieux d'environ 4 500 ans — a été séquencé et publié. Il a confirmé ce que la langue, l'artisanat et les visages suggéraient déjà : les Égyptiens modernes présentent une continuité génétique substantielle avec la population antique de la vallée, avec un mélange naturel au cours de millénaires de commerce et de conquête. Le projet de génome de référence égyptien vise désormais 25 000 génomes et un centre national du génome.",
