  "Living practices traced across millennia":
    "Pratiques vivantes tracées à travers les millénaires",
  "Local Producers": "Producteurs Locaux",
  "Locally produced collections": "Collections produites localement",
  "Long before the 27 governorates, Egypt was 42 nomes, then Roman provinces, then Coptic bishoprics, then Islamic wilayat and Mamluk iqta'. The borders moved; the logic never did — the river organises the country. Read the ancient province map next to today's administrative divisions and the continuity becomes obvious: the same clusters of settlement, the same corridors, the same names surviving in modern towns.":
    "Bien avant les 27 gouvernorats, l'Égypte était composée de 42 nomes, puis de provinces romaines, puis d'évêchés coptes, puis de wilayat islamiques et d'iqta' mamelouks. Les frontières ont bougé; la logique, jamais — le fleuve organise le pays. Lisez la carte des anciennes provinces à côté des divisions administratives actuelles et la continuité devient évidente : les mêmes groupes de peuplement, les mêmes corridors, les mêmes noms qui subsistent dans les villes modernes.",
