  "Mediterranean Elegance": "Élégance Méditerranéenne",
  "Meet the maker": "Rencontrez le créateur",
  "Megiddo, Qadesh, Hattin, Ain Jalut, Damietta, October 1973 — the same valley, the same instinct. Egyptian history is not a chain of conquests but a long record of protection: of trade routes, of a river, of a way of life. This chapter sets the rulers, the famous battles, the shifting scope of influence and the peace treaties Egypt signed side by side, so the story reads as strategy rather than spectacle.":
    "Megiddo, Qadesh, Hattin, Ain Jalut, Damiette, Octobre 1973 — la même vallée, le même instinct. L'histoire égyptienne n'est pas une chaîne de conquêtes mais un long registre de protection : des routes commerciales, d'un fleuve, d'un mode de vie. Ce chapitre présente les souverains, les batailles célèbres, l'évolution de la sphère d'influence et les traités de paix signés par l'Égypte côte à côte, afin que l'histoire se lise comme une stratégie plutôt qu'un spectacle.",
  "Meidum Pyramid": "Pyramide de Meïdoum",
