  "Copper hammered in the same alleys since the Mamluks, looms still threaded by hand, spice sacks opened at dawn, fields worked at the pace of the flood. Egypt's crafts are not heritage displays — they are working businesses you can visit, commission from and buy. This chapter opens the workshops, the souks, the farms and the ordinary street so travellers can plan a day inside the real economy of the country.":
    "Kupfer, das seit den Mamluken in denselben Gassen gehämmert wird, Webstühle, die noch von Hand gefädelt werden, Gewürzsäcke, die im Morgengrauen geöffnet werden, Felder, die im Rhythmus der Flut bearbeitet werden. Ägyptens Handwerk sind keine Heritage-Ausstellungen – sie sind funktionierende Unternehmen, die Sie besuchen, beauftragen und kaufen können. Dieses Kapitel öffnet die Werkstätten, die Souks, die Bauernhöfe und die gewöhnliche Straße, damit Reisende einen Tag in der realen Wirtschaft des Landes planen können.",
  "Copper, clay, glass, palm fibre and applique — living crafts practised in the same quarters for centuries. Meet the makers, watch the work, buy directly at fair prices.":
    "Kupfer, Ton, Glas, Palmfaser und Applikationen – lebendiges Handwerk, das seit Jahrhunderten in denselben Vierteln praktiziert wird. Treffen Sie die Hersteller, beobachten Sie die Arbeit, kaufen Sie direkt zu fairen Preisen.",
