  "Egyptian tailoring, textiles and handmade crafts":
    "Ägyptische Schneiderei, Textilien und handgefertigte Kunsthandwerke",
  "Egyptians have been baking, brewing and pickling on the same riverbank for five thousand years. Ful and taameya open the morning, molokhia and mahshi hold the family lunch, and hibiscus, sugarcane and mint tea close the night. The plates below trace the line from ancient jars and clay pitchers to the street classics visitors queue for today — a cuisine that never needed reinvention because it never stopped being cooked.":
    "Ägypter backen, brauen und pökeln seit fünftausend Jahren am selben Flussufer. Ful und Taameya eröffnen den Morgen, Molokhia und Mahshi halten das Familienmittagessen zusammen, und Hibiskus-, Zuckerrohr- und Minztee beschließen die Nacht. Die folgenden Gerichte zeichnen die Linie von antiken Krügen und Tonkannen bis zu den Straßenklassikern nach, für die Besucher heute Schlange stehen – eine Küche, die nie neu erfunden werden musste, weil sie nie aufgehört hat, gekocht zu werden.",
  "Eight illustrated chapters that turn a national archive into something you can browse, plan a trip around and invest in. Every plate is documented, every era is placed, and every chapter connects to a live part of the platform.":
    "Acht illustrierte Kapitel, die ein nationales Archiv in etwas verwandeln, das Sie durchsuchen, eine Reise darum planen und in das Sie investieren können. Jedes Gericht ist dokumentiert, jede Epoche ist eingeordnet und jedes Kapitel ist mit einem Live-Teil der Plattform verbunden.",
  "El Gouna": "El Gouna",
  "El Tor": "El Tor",
  "Endless stories": "Endlose Geschichten",
  "English text": "Englischer Text",
  "Enquire & order": "Anfragen & bestellen",
