  "Eras ready for production": "Epochen bereit zur Produktion",
  Events: "Events",
  "Events & Festivals": "Veranstaltungen & Festivals",
  "Every era in this encyclopedia is a script waiting for a camera. Egypt One's film desk exists to turn documented history into world-class Egyptian films, series and animation — shot in Egypt, produced by Egyptian talent, distributed globally. For investors it is a pipeline: studios, locations, post-production, training and film tourism. For visitors it is a reason to stand where the scene was shot.":
    "Jede Epoche in dieser Enzyklopädie ist ein Drehbuch, das auf eine Kamera wartet. Der Film-Desk von Egypt One hat es sich zur Aufgabe gemacht, dokumentierte Geschichte in erstklassige ägyptische Filme, Serien und Animationen zu verwandeln – in Ägypten gedreht, von ägyptischen Talenten produziert und weltweit vertrieben. Für Investoren ist es eine Pipeline: Studios, Drehorte, Postproduktion, Ausbildung und Filmtourismus. Für Besucher ist es ein Grund, dort zu stehen, wo die Szene gedreht wurde.",
  "Every flag Egypt has raised tells you who was standing on the riverbank that century. The crescent of the Khedivate, the tricolour of 1952, the two stars of the United Arab Republic, the Eagle of Saladin still on the mast today — read in sequence, they are a national autobiography in cloth. Beside them stand the coats of arms, the official flags of the state's institutions, and the anthems Egyptians have sung from *Salam Li Misr* to *Bilady, Bilady, Bilady*.":
    "Jede Flagge, die Ägypten gehisst hat, verrät Ihnen, wer in diesem Jahrhundert am Flussufer stand. Der Halbmond des Khedivats, die Trikolore von 1952, die zwei Sterne der Vereinigten Arabischen Republik, der Adler Saladins, der noch heute am Mast weht – in ihrer Reihenfolge gelesen sind sie eine nationale Autobiografie in Stoff. Daneben stehen die Wappen, die offiziellen Flaggen der staatlichen Institutionen und die Hymnen, die Ägypter von *Salam Li Misr* bis *Bilady, Bilady, Bilady* gesungen haben.",
  "Every listed mill carries a traceable certification code.":
    "Jede gelistete Mühle trägt einen rückverfolgbaren Zertifizierungscode.",
