  "From pre-dynastic to Fatimid": "Von der vordynastischen Zeit bis zu den Fatimiden",
  "From the Fourth Cataract to the Euphrates: military, political and cultural projection.":
    "Vom Vierten Katarakt bis zum Euphrat: militärische, politische und kulturelle Projektion.",
  "From the Ottoman era to the present tricolour, with the story behind each change.":
    "Von der osmanischen Ära bis zur heutigen Trikolore, mit der Geschichte hinter jeder Änderung.",
  "From the embroidered Siwan gowns of the Western Desert to the indigo galabeyas of the Delta, Egyptian dress is a living map. Each governorate keeps its own stitch, colour code and headwrap — patterns that travelled with caravans, harvests and weddings for centuries. This chapter lays the whole republic side by side so a visitor can see, in one glance, how Cairo, Sinai, Nubia and the coast dress differently while sharing one thread.":
    "Von den bestickten Siwa-Gewändern der Westlichen Wüste bis zu den indigofarbenen Galabeyas des Deltas ist die ägyptische Kleidung eine lebendige Landkarte. Jedes Gouvernorat behält seine eigene Stichart, Farbkodierung und Kopfbedeckung – Muster, die Jahrhunderte lang mit Karawanen, Ernten und Hochzeiten reisten. Dieses Kapitel stellt die gesamte Republik nebeneinander, sodass ein Besucher auf einen Blick sehen kann, wie sich Kairo, Sinai, Nubien und die Küste unterschiedlich kleiden, während sie doch einen gemeinsamen Faden teilen.",
