  "How authority dressed itself — from pharaonic regalia to Khedivial uniforms and modern protocol.":
    "Wie sich die Autorität kleidete – von pharaonischen Insignien über khediviale Uniformen bis hin zu modernem Protokoll.",
  Hurghada: "Hurghada",
  "Hurghada marinas": "Hurghada Marinas",
  "In 2025 the first complete genome of an Old Kingdom individual — around 4,500 years old — was sequenced and published. It confirmed what the language, the crafts and the faces already suggested: modern Egyptians carry substantial genetic continuity with the ancient population of the valley, with natural admixture over millennia of trade and conquest. The Egyptian Reference Genome Project now targets 25,000 genomes and a national genome centre.":
    "Im Jahr 2025 wurde das erste vollständige Genom eines Individuums aus dem Alten Reich – etwa 4.500 Jahre alt – sequenziert und veröffentlicht. Es bestätigte, was Sprache, Handwerk und Gesichter bereits andeuteten: Moderne Ägypter weisen eine erhebliche genetische Kontinuität mit der alten Bevölkerung des Tals auf, mit natürlicher Beimischung über Jahrtausende von Handel und Eroberung. Das Egyptian Reference Genome Project strebt nun 25.000 Genome und ein nationales Genomzentrum an.",
