  "Linen kilts, pleated New Kingdom robes, Coptic tunics and early Islamic layers, era by era.":
    "Leinenkilts, plissierte Gewänder des Neuen Reiches, koptische Tuniken und frühe islamische Schichten, Epoche für Epoche.",
