  "Locally produced collections": "Lokal produzierte Kollektionen",
  "Long before the 27 governorates, Egypt was 42 nomes, then Roman provinces, then Coptic bishoprics, then Islamic wilayat and Mamluk iqta'. The borders moved; the logic never did — the river organises the country. Read the ancient province map next to today's administrative divisions and the continuity becomes obvious: the same clusters of settlement, the same corridors, the same names surviving in modern towns.":
    "Lange vor den 27 Gouvernements bestand Ägypten aus 42 Gauen, dann römischen Provinzen, dann koptischen Bistümern, dann islamischen Wilayaten und mamelukischen Iqta'. Die Grenzen verschoben sich; die Logik tat dies nie – der Fluss organisiert das Land. Lesen Sie die Karte der alten Provinzen neben den heutigen Verwaltungsgliederungen, und die Kontinuität wird offensichtlich: dieselben Siedlungsschwerpunkte, dieselben Korridore, dieselben Namen, die in modernen Städten überleben.",
