  "Meet the maker": "Treffen Sie den Hersteller",
  "Megiddo, Qadesh, Hattin, Ain Jalut, Damietta, October 1973 — the same valley, the same instinct. Egyptian history is not a chain of conquests but a long record of protection: of trade routes, of a river, of a way of life. This chapter sets the rulers, the famous battles, the shifting scope of influence and the peace treaties Egypt signed side by side, so the story reads as strategy rather than spectacle.":
    "Megiddo, Qadesch, Hattin, Ain Jalut, Damietta, Oktober 1973 – dasselbe Tal, derselbe Instinkt. Die ägyptische Geschichte ist keine Kette von Eroberungen, sondern eine lange Aufzeichnung des Schutzes: von Handelsrouten, eines Flusses, einer Lebensweise. Dieses Kapitel stellt die Herrscher, die berühmten Schlachten, den sich verlagernden Einflussbereich und die von Ägypten unterzeichneten Friedensverträge nebeneinander, damit die Geschichte eher als Strategie denn als Spektakel gelesen wird.",
