  "Content shown on this preview is demonstration data unless labelled otherwise.":
    "El contenido mostrado en esta vista previa son datos de demostración a menos que se indique lo contrario.",
  "Copper hammered in the same alleys since the Mamluks, looms still threaded by hand, spice sacks opened at dawn, fields worked at the pace of the flood. Egypt's crafts are not heritage displays — they are working businesses you can visit, commission from and buy. This chapter opens the workshops, the souks, the farms and the ordinary street so travellers can plan a day inside the real economy of the country.":
    "Cobre martillado en los mismos callejones desde los mamelucos, telares aún enhebrados a mano, sacos de especias abiertos al amanecer, campos trabajados al ritmo de la inundación. Las artesanías de Egipto no son exposiciones de patrimonio — son negocios en funcionamiento que puedes visitar, encargar y comprar. Este capítulo abre los talleres, los zocos, las granjas y la calle ordinaria para que los viajeros puedan planificar un día dentro de la economía real del país.",
  "Copper, clay, glass, palm fibre and applique — living crafts practised in the same quarters for centuries. Meet the makers, watch the work, buy directly at fair prices.":
    "Cobre, arcilla, vidrio, fibra de palma y apliques — artesanías vivas practicadas en los mismos barrios durante siglos. Conoce a los creadores, observa el trabajo, compra directamente a precios justos.",
  "Copper, glass and lanterns with a craft guide.":
    "Cobre, vidrio y faroles con un guía artesanal.",
