  "Egyptian tailoring, textiles and handmade crafts": "Sastrería, textiles y artesanía egipcia",
  "Egyptians have been baking, brewing and pickling on the same riverbank for five thousand years. Ful and taameya open the morning, molokhia and mahshi hold the family lunch, and hibiscus, sugarcane and mint tea close the night. The plates below trace the line from ancient jars and clay pitchers to the street classics visitors queue for today — a cuisine that never needed reinvention because it never stopped being cooked.":
    "Los egipcios han horneado, elaborado cerveza y encurtido en la misma orilla del río durante cinco mil años. El ful y la taameya abren la mañana, la molokhia y el mahshi acompañan el almuerzo familiar, y el hibisco, la caña de azúcar y el té de menta cierran la noche. Los platos a continuación trazan la línea desde las antiguas jarras y cántaros de arcilla hasta los clásicos callejeros por los que los visitantes hacen cola hoy en día, una cocina que nunca necesitó reinventarse porque nunca dejó de cocinarse.",
  "Eight illustrated chapters that turn a national archive into something you can browse, plan a trip around and invest in. Every plate is documented, every era is placed, and every chapter connects to a live part of the platform.":
    "Ocho capítulos ilustrados que convierten un archivo nacional en algo que puedes explorar, usar para planificar un viaje e invertir. Cada plato está documentado, cada era está contextualizada y cada capítulo se conecta a una parte activa de la plataforma.",
  "El Gouna": "El Gouna",
  "El Tor": "El Tor",
  "Endless stories": "Historias infinitas",
  "English text": "Texto en inglés",
  "Enquire & order": "Consultar y pedir",
  Entertainment: "Entretenimiento",
  "Entertainment & Leisure": "Entretenimiento y ocio",
  "Entertainment Investment": "Inversión en Entretenimiento",
  "Epics & defence": "Épicas y defensa",
  "Epics of Egypt through the ages": "Epopeyas de Egipto a través de los siglos",
  "Eras of rulers documented": "Eras de gobernantes documentadas",
  "Eras ready for production": "Eras listas para producción",
  Events: "Eventos",
  "Events & Festivals": "Eventos y festivales",
  "Every era in this encyclopedia is a script waiting for a camera. Egypt One's film desk exists to turn documented history into world-class Egyptian films, series and animation — shot in Egypt, produced by Egyptian talent, distributed globally. For investors it is a pipeline: studios, locations, post-production, training and film tourism. For visitors it is a reason to stand where the scene was shot.":
    "Cada era en esta enciclopedia es un guion esperando una cámara. La mesa de cine de Egypt One existe para convertir la historia documentada en películas, series y animaciones egipcias de clase mundial, filmadas en Egipto, producidas por talento egipcio y distribuidas globalmente. Para los inversores es una cadena de producción: estudios, localizaciones, postproducción, formación y turismo cinematográfico. Para los visitantes es una razón para pararse donde se filmó la escena.",
  "Every flag Egypt has raised tells you who was standing on the riverbank that century. The crescent of the Khedivate, the tricolour of 1952, the two stars of the United Arab Republic, the Eagle of Saladin still on the mast today — read in sequence, they are a national autobiography in cloth. Beside them stand the coats of arms, the official flags of the state's institutions, and the anthems Egyptians have sung from *Salam Li Misr* to *Bilady, Bilady, Bilady*.":
    "Cada bandera que Egipto ha izado te dice quién estaba en la orilla del río ese siglo. El creciente del Jedivato, la tricolor de 1952, las dos estrellas de la República Árabe Unida, el Águila de Saladino todavía en el mástil hoy —leídas en secuencia, son una autobiografía nacional en tela. Junto a ellas se encuentran los escudos de armas, las banderas oficiales de las instituciones del estado y los himnos que los egipcios han cantado desde *Salam Li Misr* hasta *Bilady, Bilady, Bilady*.",
  "Every listed mill carries a traceable certification code.":
    "Cada fábrica listada lleva un código de certificación rastreable.",
  "Evolution of the Egyptian flag through the ages":
    "Evolución de la bandera egipcia a través de los siglos",
