  "From Miescher in 1869 to the first complete Old Kingdom genome and the national genome centre.":
    "Desde Miescher en 1869 hasta el primer genoma completo del Reino Antiguo y el centro nacional del genoma.",
  "From pre-dynastic to Fatimid": "Desde el predinástico hasta el fatimí",
  "From the Fourth Cataract to the Euphrates: military, political and cultural projection.":
    "Desde la Cuarta Catarata hasta el Éufrates: proyección militar, política y cultural.",
  "From the Ottoman era to the present tricolour, with the story behind each change.":
    "Desde la era otomana hasta la tricolor actual, con la historia detrás de cada cambio.",
  "From the embroidered Siwan gowns of the Western Desert to the indigo galabeyas of the Delta, Egyptian dress is a living map. Each governorate keeps its own stitch, colour code and headwrap — patterns that travelled with caravans, harvests and weddings for centuries. This chapter lays the whole republic side by side so a visitor can see, in one glance, how Cairo, Sinai, Nubia and the coast dress differently while sharing one thread.":
    "Desde los vestidos siwan bordados del Desierto Occidental hasta las galabeyas índigo del Delta, la vestimenta egipcia es un mapa vivo. Cada gobernación mantiene su propia puntada, código de color y tocado, patrones que viajaron con caravanas, cosechas y bodas durante siglos. Este capítulo presenta toda la república lado a lado para que un visitante pueda ver, de un vistazo, cómo El Cairo, el Sinaí, Nubia y la costa se visten de manera diferente mientras comparten un hilo común.",
