  "How authority dressed itself — from pharaonic regalia to Khedivial uniforms and modern protocol.":
    "Cómo se vestía la autoridad: desde la vestimenta faraónica hasta los uniformes jediviales y el protocolo moderno.",
  Hurghada: "Hurgada",
  "Hurghada marinas": "Puertos deportivos de Hurgada",
  "In 2025 the first complete genome of an Old Kingdom individual — around 4,500 years old — was sequenced and published. It confirmed what the language, the crafts and the faces already suggested: modern Egyptians carry substantial genetic continuity with the ancient population of the valley, with natural admixture over millennia of trade and conquest. The Egyptian Reference Genome Project now targets 25,000 genomes and a national genome centre.":
    "En 2025, el primer genoma completo de un individuo del Reino Antiguo —de unos 4.500 años de antigüedad— fue secuenciado y publicado. Esto confirmó lo que el idioma, las artesanías y los rostros ya sugerían: los egipcios modernos poseen una continuidad genética sustancial con la antigua población del valle, con una mezcla natural a lo largo de milenios de comercio y conquista. El Proyecto del Genoma de Referencia Egipcio ahora tiene como objetivo 25.000 genomas y un centro nacional del genoma.",
