  "Linen kilts, pleated New Kingdom robes, Coptic tunics and early Islamic layers, era by era.":
    "Faldas escocesas de lino, túnicas plisadas del Nuevo Reino, túnicas coptas y capas islámicas tempranas, era por era.",
