  "Local Producers": "Productores locales",
  "Locally produced collections": "Colecciones de producción local",
  "Long before the 27 governorates, Egypt was 42 nomes, then Roman provinces, then Coptic bishoprics, then Islamic wilayat and Mamluk iqta'. The borders moved; the logic never did — the river organises the country. Read the ancient province map next to today's administrative divisions and the continuity becomes obvious: the same clusters of settlement, the same corridors, the same names surviving in modern towns.":
    "Mucho antes de las 27 gobernaciones, Egipto era 42 nomos, luego provincias romanas, luego obispados coptos, luego wilayat islámicos e iqta' mamelucos. Las fronteras se movieron; la lógica nunca lo hizo — el río organiza el país. Lea el mapa de la antigua provincia junto a las divisiones administrativas actuales y la continuidad se hace obvia: los mismos grupos de asentamientos, los mismos corredores, los mismos nombres que sobreviven en las ciudades modernas.",
