  "Meet the maker": "Conoce al creador",
  "Megiddo, Qadesh, Hattin, Ain Jalut, Damietta, October 1973 — the same valley, the same instinct. Egyptian history is not a chain of conquests but a long record of protection: of trade routes, of a river, of a way of life. This chapter sets the rulers, the famous battles, the shifting scope of influence and the peace treaties Egypt signed side by side, so the story reads as strategy rather than spectacle.":
    "Megido, Qadesh, Hattin, Ain Jalut, Damietta, Octubre de 1973 — el mismo valle, el mismo instinto. La historia egipcia no es una cadena de conquistas sino un largo registro de protección: de rutas comerciales, de un río, de una forma de vida. Este capítulo presenta a los gobernantes, las famosas batallas, el cambiante alcance de la influencia y los tratados de paz que Egipto firmó, uno al lado del otro, para que la historia se lea como estrategia en lugar de espectáculo.",
