  "Egyptian tailoring, textiles and handmade crafts": "Sartoria, tessuti e artigianato egiziano",
  "Egyptians have been baking, brewing and pickling on the same riverbank for five thousand years. Ful and taameya open the morning, molokhia and mahshi hold the family lunch, and hibiscus, sugarcane and mint tea close the night. The plates below trace the line from ancient jars and clay pitchers to the street classics visitors queue for today — a cuisine that never needed reinvention because it never stopped being cooked.":
    "Gli Egiziani cuociono al forno, fermentano e sottaceto sulla stessa riva del fiume da cinquemila anni. Ful e taameya aprono la mattina, molokhia e mahshi sostengono il pranzo di famiglia, e ibisco, canna da zucchero e tè alla menta chiudono la notte. I piatti qui sotto tracciano la linea dalle antiche giare e brocche d'argilla ai classici di strada per cui i visitatori fanno la fila oggi — una cucina che non ha mai avuto bisogno di reinventarsi perché non ha mai smesso di essere cucinata.",
  "Eight illustrated chapters that turn a national archive into something you can browse, plan a trip around and invest in. Every plate is documented, every era is placed, and every chapter connects to a live part of the platform.":
    "Otto capitoli illustrati che trasformano un archivio nazionale in qualcosa che puoi sfogliare, pianificare un viaggio intorno e in cui investire. Ogni piatto è documentato, ogni era è collocata, e ogni capitolo si collega a una parte live della piattaforma.",
  "El Gouna": "El Gouna",
