  "From the Ottoman era to the present tricolour, with the story behind each change.":
    "Dall'era ottomana all'attuale tricolore, con la storia dietro ogni cambiamento.",
  "From the embroidered Siwan gowns of the Western Desert to the indigo galabeyas of the Delta, Egyptian dress is a living map. Each governorate keeps its own stitch, colour code and headwrap — patterns that travelled with caravans, harvests and weddings for centuries. This chapter lays the whole republic side by side so a visitor can see, in one glance, how Cairo, Sinai, Nubia and the coast dress differently while sharing one thread.":
    "Dagli abiti ricamati di Siwa del Deserto Occidentale alle galabeya indaco del Delta, l'abbigliamento egiziano è una mappa vivente. Ogni governatorato mantiene il proprio punto, codice colore e copricapo — modelli che hanno viaggiato con carovane, raccolti e matrimoni per secoli. Questo capitolo mette a confronto l'intera repubblica in modo che un visitatore possa vedere, con un solo sguardo, come il Cairo, il Sinai, la Nubia e la costa si vestano in modo diverso pur condividendo un unico filo.",
