  "How authority dressed itself — from pharaonic regalia to Khedivial uniforms and modern protocol.":
    "Come l'autorità si vestiva — dalle insegne faraoniche alle uniformi khediviali e al protocollo moderno.",
  Hurghada: "Hurghada",
  "Hurghada marinas": "Porti turistici di Hurghada",
  "In 2025 the first complete genome of an Old Kingdom individual — around 4,500 years old — was sequenced and published. It confirmed what the language, the crafts and the faces already suggested: modern Egyptians carry substantial genetic continuity with the ancient population of the valley, with natural admixture over millennia of trade and conquest. The Egyptian Reference Genome Project now targets 25,000 genomes and a national genome centre.":
    "Nel 2025 è stato sequenziato e pubblicato il primo genoma completo di un individuo dell'Antico Regno — di circa 4.500 anni. Ha confermato ciò che la lingua, l'artigianato e i volti già suggerivano: gli Egiziani moderni presentano una sostanziale continuità genetica con l'antica popolazione della valle, con una naturale mescolanza nel corso di millenni di scambi commerciali e conquiste. L'Egyptian Reference Genome Project ora mira a 25.000 genomi e a un centro nazionale per il genoma.",
