  "Locally produced collections": "Collezioni prodotte localmente",
  "Long before the 27 governorates, Egypt was 42 nomes, then Roman provinces, then Coptic bishoprics, then Islamic wilayat and Mamluk iqta'. The borders moved; the logic never did — the river organises the country. Read the ancient province map next to today's administrative divisions and the continuity becomes obvious: the same clusters of settlement, the same corridors, the same names surviving in modern towns.":
    "Molto prima dei 27 governatorati, l'Egitto era composto da 42 nomi, poi province romane, poi vescovadi copti, poi wilayat islamiche e iqta' mamelucchi. I confini si muovevano; la logica no — il fiume organizza il paese. Leggete l'antica mappa delle province accanto alle divisioni amministrative odierne e la continuità diventa evidente: gli stessi agglomerati di insediamenti, gli stessi corridoi, gli stessi nomi che sopravvivono nelle città moderne.",
