  "Meet the maker": "Incontra l'artigiano",
  "Megiddo, Qadesh, Hattin, Ain Jalut, Damietta, October 1973 — the same valley, the same instinct. Egyptian history is not a chain of conquests but a long record of protection: of trade routes, of a river, of a way of life. This chapter sets the rulers, the famous battles, the shifting scope of influence and the peace treaties Egypt signed side by side, so the story reads as strategy rather than spectacle.":
    "Megiddo, Qadesh, Hattin, Ain Jalut, Damietta, Ottobre 1973 — la stessa valle, lo stesso istinto. La storia egiziana non è una catena di conquiste ma un lungo registro di protezione: di rotte commerciali, di un fiume, di uno stile di vita. Questo capitolo affianca i governanti, le famose battaglie, l'ambito mutevole di influenza e i trattati di pace firmati dall'Egitto, in modo che la storia si legga come strategia piuttosto che come spettacolo.",
