  "Egyptian flags, emblems and anthems": "Египетские флаги, эмблемы и гимны",
  "Egyptian markets and trade": "Египетские рынки и торговля",
  "Egyptian national anthems and official songs through history":
    "Египетские национальные гимны и официальные песни на протяжении истории",
  "Egyptian spices and hibiscus in copper bowls": "Египетские специи и гибискус в медных чашах",
  "Egyptian tailoring, textiles and handmade crafts":
    "Египетский пошив, текстиль и изделия ручной работы",
  "Egyptians have been baking, brewing and pickling on the same riverbank for five thousand years. Ful and taameya open the morning, molokhia and mahshi hold the family lunch, and hibiscus, sugarcane and mint tea close the night. The plates below trace the line from ancient jars and clay pitchers to the street classics visitors queue for today — a cuisine that never needed reinvention because it never stopped being cooked.":
    "Египтяне пекут, варят и консервируют на одном и том же берегу реки уже пять тысяч лет. Фул и таамейя открывают утро, молокхия и махши сопровождают семейный обед, а чай из гибискуса, сахарного тростника и мяты завершает вечер. Представленные ниже блюда прослеживают путь от древних кувшинов и глиняных сосудов до уличных блюд, за которыми сегодня выстраиваются очереди — кухня, которая никогда не нуждалась в переосмыслении, потому что ее никогда не переставали готовить.",
  "Eight illustrated chapters that turn a national archive into something you can browse, plan a trip around and invest in. Every plate is documented, every era is placed, and every chapter connects to a live part of the platform.":
    "Восемь иллюстрированных глав, которые превращают национальный архив в нечто, что можно просматривать, планировать поездки и инвестировать. Каждое блюдо документировано, каждая эпоха представлена, и каждая глава связана с действующей частью платформы.",
  "El Gouna": "Эль-Гуна",
  "El Tor": "Эль-Тур",
  "Endless stories": "Бесконечные истории",
  "English text": "Английский текст",
  "Enquire & order": "Запросить и заказать",
  Entertainment: "Развлечения",
  "Entertainment & Leisure": "Развлечения и досуг",
  "Entertainment Investment": "Инвестиции в развлечения",
  "Epics & defence": "Эпос и оборона",
  "Epics of Egypt through the ages": "Эпосы Египта сквозь века",
  "Eras of rulers documented": "Задокументированные эпохи правителей",
  "Eras ready for production": "Эпохи, готовые к производству",
  Events: "События",
  "Events & Festivals": "События и фестивали",
  "Every era in this encyclopedia is a script waiting for a camera. Egypt One's film desk exists to turn documented history into world-class Egyptian films, series and animation — shot in Egypt, produced by Egyptian talent, distributed globally. For investors it is a pipeline: studios, locations, post-production, training and film tourism. For visitors it is a reason to stand where the scene was shot.":
    "Каждая эпоха в этой энциклопедии — это сценарий, ожидающий камеры. Отдел кинопроектов Egypt One существует для того, чтобы превращать задокументированную историю в египетские фильмы, сериалы и анимацию мирового класса — снятые в Египте, созданные египетскими талантами и распространяемые по всему миру. Для инвесторов это целый канал: студии, локации, постпродакшн, обучение и кинотуризм. Для посетителей это повод постоять там, где снималась сцена.",
  "Every flag Egypt has raised tells you who was standing on the riverbank that century. The crescent of the Khedivate, the tricolour of 1952, the two stars of the United Arab Republic, the Eagle of Saladin still on the mast today — read in sequence, they are a national autobiography in cloth. Beside them stand the coats of arms, the official flags of the state's institutions, and the anthems Egyptians have sung from *Salam Li Misr* to *Bilady, Bilady, Bilady*.":
    "Каждый флаг, который Египет поднимал, рассказывает, кто стоял на берегу реки в том или ином столетии. Полумесяц Хедивата, триколор 1952 года, две звезды Объединенной Арабской Республики, Орел Саладина, до сих пор на мачте — прочитанные последовательно, они представляют собой национальную автобиографию в ткани. Рядом с ними стоят гербы, официальные флаги государственных учреждений и гимны, которые египтяне пели от «Салам Ли Миср» до «Билади, Билади, Билади».",
  "Every listed mill carries a traceable certification code.":
    "Каждая зарегистрированная фабрика имеет отслеживаемый код сертификации.",
