  "Hieroglyph and Coptic patterns hand-embroidered in gold thread.":
    "Иероглифические и коптские узоры, вышитые вручную золотой нитью.",
  "Historic mills plus a tailoring session.": "Исторические мельницы и сеанс кройки и шитья.",
  "Historic souks and covered bazaars where the country still does business face to face.":
    "Исторические базары и крытые рынки, где до сих пор ведётся личное деловое общение.",
  Home: "Главная",
