  Hotels: "Отели",
  "Hotels & Stays": "Отели и проживание",
  "How authority dressed itself — from pharaonic regalia to Khedivial uniforms and modern protocol.":
    "Как одевалась власть — от фараонских регалий до хедивских мундиров и современного протокола.",
  Hurghada: "Хургада",
  "Hurghada marinas": "Марины Хургады",
  "In 2025 the first complete genome of an Old Kingdom individual — around 4,500 years old — was sequenced and published. It confirmed what the language, the crafts and the faces already suggested: modern Egyptians carry substantial genetic continuity with the ancient population of the valley, with natural admixture over millennia of trade and conquest. The Egyptian Reference Genome Project now targets 25,000 genomes and a national genome centre.":
    "В 2025 году был секвенирован и опубликован первый полный геном человека эпохи Древнего царства — возрастом около 4500 лет. Это подтвердило то, на что уже указывали язык, ремёсла и лица: современные египтяне демонстрируют значительную генетическую преемственность с древним населением долины, с естественным смешением на протяжении тысячелетий торговли и завоеваний. Проект Egyptian Reference Genome Project теперь нацелен на 25 000 геномов и создание национального геномного центра.",
  "Independent design labels": "Независимые дизайнерские бренды",
  Industry: "Промышленность",
