  Jun: "Июнь",
  "Kadesh, Amasya, London, Rhodes, Camp David — Egypt at the negotiating table.":
    "Кадеш, Амасья, Лондон, Родос, Кэмп-Дэвид — Египет за столом переговоров.",
  "Kafr El Sheikh": "Кафр-эш-Шейх",
