    "Студии аппликации хайямии и мастер-класс по шитью.",
  "Kilim & khayamiya": "Килим и хайямия",
  "Kingdom crown and lions, the UAR shield, and the Eagle of Saladin in use today.":
    "Корона и львы царства, щит ОАР и Орел Саладина, используемые сегодня.",
  Klook: "Клук",
  "Know what is in season before you travel.":
    "Узнайте, что в сезоне, прежде чем отправиться в путешествие.",
  "Lake Timsah": "Озеро Тимсах",
  Language: "Язык",
  Leisure: "Досуг",
  "Licensed & Verified": "Лицензированный и проверенный",
  "Limited runs inspired by museum archives.":
    "Ограниченные серии, вдохновленные музейными архивами.",
  "Linen kilts, pleated New Kingdom robes, Coptic tunics and early Islamic layers, era by era.":
    "Льняные килты, плиссированные одеяния Нового царства, коптские туники и ранние исламские слои, эпоха за эпохой.",
  "Linguistic continuity": "Языковая преемственность",
  "Living practices traced across millennia":
    "Живые практики, прослеживаемые на протяжении тысячелетий",
  "Local Producers": "Местные производители",
  "Locally produced collections": "Коллекции местного производства",
  "Long before the 27 governorates, Egypt was 42 nomes, then Roman provinces, then Coptic bishoprics, then Islamic wilayat and Mamluk iqta'. The borders moved; the logic never did — the river organises the country. Read the ancient province map next to today's administrative divisions and the continuity becomes obvious: the same clusters of settlement, the same corridors, the same names surviving in modern towns.":
    "Задолго до 27 мухафаз Египет состоял из 42 номов, затем римских провинций, затем коптских епископств, затем исламских вилаятов и мамлюкских икта. Границы менялись; логика никогда не менялась — река организует страну. Прочтите карту древних провинций рядом с сегодняшними административными делениями, и преемственность станет очевидной: те же скопления поселений, те же коридоры, те же названия, сохранившиеся в современных городах.",
  "Loyalty & Rewards": "Лояльность и награды",
  Luxor: "Луксор",
  "Luxor Temple": "Луксорский храм",
  "Lyricists, composers and the moment each anthem entered national memory.":
    "Авторы текстов, композиторы и момент, когда каждый гимн вошел в национальную память.",
  "Made in Egypt": "Сделано в Египте",
