  "Meet the maker": "Познакомьтесь с мастером",
  "Megiddo, Qadesh, Hattin, Ain Jalut, Damietta, October 1973 — the same valley, the same instinct. Egyptian history is not a chain of conquests but a long record of protection: of trade routes, of a river, of a way of life. This chapter sets the rulers, the famous battles, the shifting scope of influence and the peace treaties Egypt signed side by side, so the story reads as strategy rather than spectacle.":
    "Мегиддо, Кадеш, Хаттин, Айн-Джалут, Дамиетта, октябрь 1973 года — та же долина, тот же инстинкт. История Египта — это не цепь завоеваний, а долгий путь защиты: торговых путей, реки, образа жизни. В этой главе правители, знаменитые битвы, меняющаяся сфера влияния и мирные договоры, подписанные Египтом, расположены рядом, так что история читается как стратегия, а не как зрелище.",
