  "Limited runs inspired by museum archives.": "受博物馆档案启发，限量发行。",
  "Linen kilts, pleated New Kingdom robes, Coptic tunics and early Islamic layers, era by era.":
    "亚麻短裙、新王国褶皱长袍、科普特束腰外衣和早期伊斯兰服饰，逐个时代呈现。",
  "Linguistic continuity": "语言连续性",
  "Living practices traced across millennia": "追溯数千年来的生活习俗",
  "Local Producers": "本地生产商",
  "Locally produced collections": "本地生产系列",
  "Long before the 27 governorates, Egypt was 42 nomes, then Roman provinces, then Coptic bishoprics, then Islamic wilayat and Mamluk iqta'. The borders moved; the logic never did — the river organises the country. Read the ancient province map next to today's administrative divisions and the continuity becomes obvious: the same clusters of settlement, the same corridors, the same names surviving in modern towns.":
    "在27个省份出现很久以前，埃及曾是42个州，之后是罗马行省，然后是科普特主教区，再后来是伊斯兰行省和马穆鲁克伊克塔。边界在变动；但其内在逻辑从未改变——河流组织着这个国家。将古代省份地图与今天的行政区划并列阅读，其连续性显而易见：相同的聚居区、相同的走廊、相同的名称在现代城镇中得以保留。",
  "Loyalty & Rewards": "忠诚度与奖励",
  Luxor: "卢克索",
  "Luxor Temple": "卢克索神庙",
