  "Contact the film desk": "फिल्म डेस्क से संपर्क करें",
  "Content shown on this preview is demonstration data unless labelled otherwise.":
    "इस पूर्वावलोकन में दिखाई गई सामग्री प्रदर्शन डेटा है, जब तक कि अन्यथा लेबल न किया गया हो।",
  "Copper hammered in the same alleys since the Mamluks, looms still threaded by hand, spice sacks opened at dawn, fields worked at the pace of the flood. Egypt's crafts are not heritage displays — they are working businesses you can visit, commission from and buy. This chapter opens the workshops, the souks, the farms and the ordinary street so travellers can plan a day inside the real economy of the country.":
    "मामलुक काल से ही उन्हीं गलियों में तांबा पीटा जाता रहा है, करघे अभी भी हाथों से धागे से बुने जाते हैं, सुबह होते ही मसाले के बोरे खोले जाते हैं, खेत बाढ़ की गति से काम करते हैं। मिस्र के शिल्प विरासत प्रदर्शन नहीं हैं — वे ऐसे कामकाजी व्यवसाय हैं जहाँ आप जा सकते हैं, ऑर्डर दे सकते हैं और खरीदारी कर सकते हैं। यह अध्याय कार्यशालाओं, सूकों, खेतों और सामान्य सड़कों को खोलता है ताकि यात्री देश की वास्तविक अर्थव्यवस्था के भीतर एक दिन की योजना बना सकें।",
  "Copper, clay, glass, palm fibre and applique — living crafts practised in the same quarters for centuries. Meet the makers, watch the work, buy directly at fair prices.":
    "तांबा, मिट्टी, काँच, ताड़ के रेशे और एप्लिक — सदियों से उन्हीं मोहल्लों में प्रचलित जीवित शिल्प। निर्माताओं से मिलें, काम देखें, उचित मूल्य पर सीधे खरीदें।",
  "Copper, glass and lanterns with a craft guide.": "शिल्प गाइड के साथ तांबा, काँच और लालटेन।",
