  "Egyptian tailoring, textiles and handmade crafts": "मिस्र की सिलाई, वस्त्र और हस्तशिल्प",
  "Egyptians have been baking, brewing and pickling on the same riverbank for five thousand years. Ful and taameya open the morning, molokhia and mahshi hold the family lunch, and hibiscus, sugarcane and mint tea close the night. The plates below trace the line from ancient jars and clay pitchers to the street classics visitors queue for today — a cuisine that never needed reinvention because it never stopped being cooked.":
    "मिस्रवासी पाँच हज़ार सालों से एक ही नदी किनारे पर बेकिंग, ब्रूइंग और अचार बनाने का काम कर रहे हैं। फौल और तआमिया सुबह की शुरुआत करते हैं, मोलोखिया और महशी परिवार के दोपहर के भोजन का हिस्सा होते हैं, और गुड़हल, गन्ना तथा पुदीने की चाय रात को ख़त्म करती है। नीचे दिए गए व्यंजन प्राचीन जार और मिट्टी के घड़े से लेकर आज के उन स्ट्रीट क्लासिक्स तक की एक कड़ी बनाते हैं जिनके लिए आगंतुक कतार में खड़े होते हैं—एक ऐसा व्यंजन जिसे कभी नए सिरे से गढ़ने की ज़रूरत नहीं पड़ी क्योंकि यह कभी बनना बंद नहीं हुआ।",
  "Eight illustrated chapters that turn a national archive into something you can browse, plan a trip around and invest in. Every plate is documented, every era is placed, and every chapter connects to a live part of the platform.":
    "आठ सचित्र अध्याय जो एक राष्ट्रीय संग्रह को कुछ ऐसा बनाते हैं जिसे आप ब्राउज़ कर सकते हैं, उसके इर्द-गिर्द यात्रा की योजना बना सकते हैं और उसमें निवेश कर सकते हैं। हर प्लेट का दस्तावेज़ीकरण किया गया है, हर युग को स्थापित किया गया है, और हर अध्याय प्लेटफॉर्म के एक सक्रिय हिस्से से जुड़ा हुआ है।",
  "El Gouna": "एल गौना",
  "El Tor": "एल टोर",
  "Endless stories": "अनंत कहानियाँ",
  "English text": "अंग्रेजी पाठ",
  "Enquire & order": "पूछताछ करें और ऑर्डर करें",
  Entertainment: "मनोरंजन",
  "Entertainment & Leisure": "मनोरंजन और अवकाश",
  "Entertainment Investment": "मनोरंजन में निवेश",
  "Epics & defence": "महाकाव्य और रक्षा",
  "Epics of Egypt through the ages": "युगों-युगों से मिस्र के महाकाव्य",
  "Eras of rulers documented": "शासकों के युग दस्तावेज़ीकृत",
  "Eras ready for production": "उत्पादन के लिए तैयार युग",
  Events: "आयोजन",
  "Events & Festivals": "आयोजन और त्यौहार",
  "Every era in this encyclopedia is a script waiting for a camera. Egypt One's film desk exists to turn documented history into world-class Egyptian films, series and animation — shot in Egypt, produced by Egyptian talent, distributed globally. For investors it is a pipeline: studios, locations, post-production, training and film tourism. For visitors it is a reason to stand where the scene was shot.":
    "इस विश्वकोश का हर युग एक स्क्रिप्ट है जो कैमरे का इंतज़ार कर रही है। Egypt One का फिल्म डेस्क दस्तावेज़ीकृत इतिहास को विश्व स्तरीय मिस्री फिल्मों, सीरीज़ और एनिमेशन में बदलने के लिए मौजूद है — जिनकी शूटिंग मिस्र में होती है, जिनका निर्माण मिस्री प्रतिभा द्वारा किया जाता है, और जो विश्व स्तर पर वितरित की जाती हैं। निवेशकों के लिए यह एक पाइपलाइन है: स्टूडियो, स्थान, पोस्ट-प्रोडक्शन, प्रशिक्षण और फिल्म पर्यटन। आगंतुकों के लिए यह उस जगह खड़े होने का एक कारण है जहाँ दृश्य फिल्माया गया था।",
  "Every flag Egypt has raised tells you who was standing on the riverbank that century. The crescent of the Khedivate, the tricolour of 1952, the two stars of the United Arab Republic, the Eagle of Saladin still on the mast today — read in sequence, they are a national autobiography in cloth. Beside them stand the coats of arms, the official flags of the state's institutions, and the anthems Egyptians have sung from *Salam Li Misr* to *Bilady, Bilady, Bilady*.":
    "मिस्र ने जो भी झंडा उठाया है, वह बताता है कि उस सदी में नदी किनारे कौन खड़ा था। खेदिवेट का अर्धचंद्र, 1952 का तिरंगा, संयुक्त अरब गणराज्य के दो सितारे, सलादीन का चील आज भी मस्तूल पर — क्रम से पढ़ने पर, वे कपड़े में एक राष्ट्रीय आत्मकथा हैं। उनके बगल में राजकीय संस्थाओं के प्रतीक चिह्न, आधिकारिक झंडे और वे गान खड़े हैं जो मिस्रवासियों ने *सलाम ली मिस्र* से लेकर *बिलादी, बिलादी, बिलादी* तक गाए हैं।",
  "Every listed mill carries a traceable certification code.":
    "सूचीबद्ध हर मिल एक ट्रेस करने योग्य प्रमाणीकरण कोड रखती है।",
