  "From Ancient Egyptian to Coptic to Arabic": "प्राचीन मिस्र से कॉप्टिक से अरबी तक",
  "From Ayyubid to today": "अय्यूबी से आज तक",
  "From Megiddo and Actium to Ain Jalut, Tel El Kebir and the October War.":
    "मेगिडो और एक्टियम से ऐन जालुत, टेल एल केबीर और अक्टूबर युद्ध तक।",
  "From Miescher in 1869 to the first complete Old Kingdom genome and the national genome centre.":
    "1869 में मिश्चर से पहले पूर्ण पुराने साम्राज्य के जीनोम और राष्ट्रीय जीनोम केंद्र तक।",
  "From pre-dynastic to Fatimid": "पूर्व-राजवंशीय से फातिमी तक",
  "From the Fourth Cataract to the Euphrates: military, political and cultural projection.":
    "चौथे जलप्रपात से यूफ्रेट्स तक: सैन्य, राजनीतिक और सांस्कृतिक प्रक्षेपण।",
  "From the Ottoman era to the present tricolour, with the story behind each change.":
    "ओटोमन युग से लेकर वर्तमान तिरंगे तक, प्रत्येक परिवर्तन के पीछे की कहानी के साथ।",
  "From the embroidered Siwan gowns of the Western Desert to the indigo galabeyas of the Delta, Egyptian dress is a living map. Each governorate keeps its own stitch, colour code and headwrap — patterns that travelled with caravans, harvests and weddings for centuries. This chapter lays the whole republic side by side so a visitor can see, in one glance, how Cairo, Sinai, Nubia and the coast dress differently while sharing one thread.":
    "पश्चिमी रेगिस्तान के कढ़ाई वाले सीवान गाउन से लेकर डेल्टा के नीले गलाबेया तक, मिस्र की पोशाक एक जीवंत मानचित्र है। प्रत्येक प्रांत अपनी सिलाई, रंग कोड और सिर ढकने का तरीका रखता है - ऐसे पैटर्न जो सदियों से कारवां, कटाई और शादियों के साथ यात्रा करते रहे। यह अध्याय पूरे गणराज्य को एक साथ प्रस्तुत करता है ताकि एक आगंतुक एक नज़र में देख सके कि काहिरा, सिनाई, नुबिया और तट कैसे अलग कपड़े पहनते हैं, जबकि एक ही धागा साझा करते हैं।",
