  "How authority dressed itself — from pharaonic regalia to Khedivial uniforms and modern protocol.":
    "अधिकारियों ने खुद को कैसे सजाया - फिरौन के शाही वस्त्रों से लेकर खेदिवियल यूनिफॉर्म और आधुनिक प्रोटोकॉल तक।",
  Hurghada: "हर्गहाडा",
  "Hurghada marinas": "हर्गहाडा मरीना",
  "In 2025 the first complete genome of an Old Kingdom individual — around 4,500 years old — was sequenced and published. It confirmed what the language, the crafts and the faces already suggested: modern Egyptians carry substantial genetic continuity with the ancient population of the valley, with natural admixture over millennia of trade and conquest. The Egyptian Reference Genome Project now targets 25,000 genomes and a national genome centre.":
    "2025 में, एक प्राचीन साम्राज्य के व्यक्ति — लगभग 4,500 साल पुराना — का पहला पूर्ण जीनोम अनुक्रमित और प्रकाशित किया गया था। इसने पुष्टि की कि भाषा, शिल्प और चेहरे पहले ही क्या सुझाते थे: आधुनिक मिस्रियों का घाटी की प्राचीन आबादी के साथ पर्याप्त आनुवंशिक निरंतरता है, व्यापार और विजय के सहस्राब्दियों में प्राकृतिक मिश्रण के साथ। मिस्र का संदर्भ जीनोम परियोजना अब 25,000 जीनोम और एक राष्ट्रीय जीनोम केंद्र को लक्षित करती है।",
