  "Locally produced collections": "स्थानीय रूप से उत्पादित संग्रह",
  "Long before the 27 governorates, Egypt was 42 nomes, then Roman provinces, then Coptic bishoprics, then Islamic wilayat and Mamluk iqta'. The borders moved; the logic never did — the river organises the country. Read the ancient province map next to today's administrative divisions and the continuity becomes obvious: the same clusters of settlement, the same corridors, the same names surviving in modern towns.":
    "27 राज्यपालों के बनने से बहुत पहले, मिस्र में 42 नोमेस थे, फिर रोमन प्रांत, फिर कॉप्टिक बिशप्रिक, फिर इस्लामी विलायत और ममलुक इक्ता। सीमाएँ बदलती रहीं; तर्क कभी नहीं बदला — नदी देश को व्यवस्थित करती है। आज के प्रशासनिक प्रभागों के बगल में प्राचीन प्रांत के नक्शे को पढ़ें और निरंतरता स्पष्ट हो जाती है: बस्तियों के वही समूह, वही गलियारे, आधुनिक शहरों में जीवित वही नाम।",
  "Loyalty & Rewards": "निष्ठा और पुरस्कार",
